record.field:
for project in records:
    if not project.phu_trach_id:
        # Tìm tất cả nhân viên có chức vụ Giám đốc hoặc Trưởng phòng và đang làm việc (active)
        candidates = env['hr.employee'].search([
            ('job_id.name', 'in', ['Giám đốc', 'Trưởng phòng']),
            ('active', '=', True)
        ])
        if not candidates:
            continue

        # Tính số dự án hiện tại (chưa hoàn thành, chưa hủy) mà mỗi nhân viên đang phụ trách
        domain_not_completed = [('trang_thai', 'not in', ['hoan_thanh', 'huy'])]
        counts = {}
        for emp in candidates:
            count = env['du_an'].search_count([
                ('phu_trach_id', '=', emp.id)
            ] + domain_not_completed)
            counts[emp.id] = count

        # Sắp xếp nhân viên theo số lượng dự án tăng dần, chọn người đầu tiên
        sorted_emps = sorted(candidates, key=lambda e: counts[e.id])
        chosen = sorted_emps[0]
        project.write({'phu_trach_id': chosen.id})
